import{_ as e,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"IaC：基础对象与机制","description":"按 声明目标、state 身份映射、依赖图与两种锁 的实际关系组织。","frontmatter":{"title":"IaC：基础对象与机制","description":"按 声明目标、state 身份映射、依赖图与两种锁 的实际关系组织。","showdocs":{"topics":[{"id":"iac","title":"基础设施自动化","link":"/topics/iac/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"基础设施自动化机制与任务课程","summary":"按 声明目标、state 身份映射、依赖图与两种锁 的实际关系组织。","status":"active","related":[{"title":"基础设施自动化：编写基础设施声明与计划门禁","link":"/systems/cloud-infrastructure/iac/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"IaC：发布、排障与恢复练习","link":"/systems/cloud-infrastructure/iac/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"基础设施自动化：编写基础设施声明与计划门禁","link":"/systems/cloud-infrastructure/iac/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"基础设施自动化：编写基础设施声明与计划门禁","link":"/systems/cloud-infrastructure/iac/plus/practice/application"}},"headers":[],"relativePath":"systems/cloud-infrastructure/iac/state-and-plan.md","filePath":"systems/cloud-infrastructure/iac/state-and-plan.md"}'),s={name:"systems/cloud-infrastructure/iac/state-and-plan.md"};function l(o,a,c,n,p,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="iac-基础对象与机制" tabindex="-1">IaC：基础对象与机制 <a class="header-anchor" href="#iac-基础对象与机制" aria-label="Permalink to &quot;IaC：基础对象与机制&quot;">​</a></h1><h2 id="part-1" tabindex="-1">声明、计划、状态与执行入口 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;声明、计划、状态与执行入口 {#part-1}&quot;">​</a></h2><p>基础设施自动化把声明、状态映射与远端真实资源联系起来。先读懂计划中的创建、修改、替换和删除，再理解依赖与锁；版本控制中的声明回退不等同远端资源与数据自动恢复。</p><h3 id="part-1-declarative" tabindex="-1">声明目标与执行动作 <a class="header-anchor" href="#part-1-declarative" aria-label="Permalink to &quot;声明目标与执行动作 {#part-1-declarative}&quot;">​</a></h3><p>IaC声明目标描述希望管理的资源关系，工具比较配置、状态与远端对象后生成计划。它不是把Shell命令换成配置文件；同样配置在不同状态、权限和真实环境下可能得到不同动作。Terraform provider实现与远端平台交互，内建terraform_data只管理本地状态中的数据对象，不创建云主机。示例不含任何provider凭据或远端服务。</p><h3 id="part-1-commands" tabindex="-1">Init、Plan和Apply入口 <a class="header-anchor" href="#part-1-commands" aria-label="Permalink to &quot;Init、Plan和Apply入口 {#part-1-commands}&quot;">​</a></h3><p>IaC命令入口分为init初始化backend与依赖、plan预览差异、apply执行已审阅计划、destroy生成删除意图。plan可能刷新并读取真实远端，validate也属于产品CLI。读者应在独立目录核对backend、workspace和变量后再自跑，避免当前目录自动加载生产配置。带-out的计划需保护权限，因为二进制计划可能包含秘密。</p><h3 id="part-1-inputs" tabindex="-1">输入、版本与隔离 <a class="header-anchor" href="#part-1-inputs" aria-label="Permalink to &quot;输入、版本与隔离 {#part-1-inputs}&quot;">​</a></h3><p>IaC输入合同要求environment只能lab，版本限制1.10族，避免无边界兼容承诺。变量文件、环境变量和CLI参数可能覆盖默认值；只读main.tf不能证明真实运行输入一致。示例只有内建terraform_data，不需要外部provider或伪造锁文件；一旦读者扩展云provider，就必须固定兼容版本、审阅依赖锁、身份与费用，本课程不提供可部署云模板。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：plan是否始终只是本地文本比较？</p><details><summary>参考解答</summary><p>不是。真实 plan 可能刷新并读取 provider 远端资源，运行前需确认目标账户、工作空间与访问范围。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><a href="https://developer.hashicorp.com/terraform/language/state" target="_blank" rel="noopener noreferrer">状态机制</a></li><li><a href="https://developer.hashicorp.com/terraform/language/state/locking" target="_blank" rel="noopener noreferrer">状态锁</a></li><li><a href="https://developer.hashicorp.com/terraform/language/resources/terraform-data" target="_blank" rel="noopener noreferrer">terraform_data</a></li></ul><p>继续阅读<a href="#part-2-state">机制</a>、<a href="/systems/cloud-infrastructure/iac/plus/practice/application#files">完整实践</a>、<a href="/systems/cloud-infrastructure/iac/operations#part-1-secrets">运维</a>、<a href="/systems/cloud-infrastructure/iac/operations#part-2-conflict">诊断</a>与<a href="/systems/cloud-infrastructure/iac/operations#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">资源映射、依赖图与并发锁 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;资源映射、依赖图与并发锁 {#part-2}&quot;">​</a></h2><p>先明确backend、workspace、变量与资源地址，再对照<a href="/systems/cloud-infrastructure/iac/plus/practice/application#files">配套示例</a>理解计划动作、未知值、状态锁及真实资源映射。</p><p>核对日期2026-10-17；适用范围：Terraform &gt;=1.10.0,&lt;1.11.0，内建terraform_data；无外部provider和云账号。固定教学族不是2026最新版本或生产升级建议，状态/锁按所选backend另行核对。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="#part-1-declarative">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-2-state" tabindex="-1">State的身份映射 <a class="header-anchor" href="#part-2-state" aria-label="Permalink to &quot;State的身份映射 {#part-2-state}&quot;">​</a></h3><p>IaC状态映射保存资源地址与远端身份的关系及已知属性，用于后续比较。state不是可随意删除的缓存，也不保证所有远端变化已同步；丢失state可能让工具计划重复创建真实对象。手工编辑JSON会破坏一致性，应在备份、独占变更与审阅下使用正式状态迁移机制。terraform_data无远端对象，仍用状态展示地址与input/output关系。</p><h3 id="part-2-plan" tabindex="-1">依赖图与替换计划 <a class="header-anchor" href="#part-2-plan" aria-label="Permalink to &quot;依赖图与替换计划 {#part-2-plan}&quot;">​</a></h3><p>IaC计划差异需要查看create/update/delete及replacement，不能只看总数。资源引用建立依赖图，执行顺序由依赖决定；无关对象可并行，文件书写顺序不构成业务顺序保证。create_before_destroy也受命名唯一性、配额和依赖制约。示例input.revision变化通常为terraform_data更新，强制替换则是另一动作；审阅器拒绝含delete的替换，避免先删后建风险。</p><h3 id="part-2-locking" tabindex="-1">State锁与依赖锁 <a class="header-anchor" href="#part-2-locking" aria-label="Permalink to &quot;State锁与依赖锁 {#part-2-locking}&quot;">​</a></h3><p>IaC状态锁保护同一backend的并发写入，是否支持由backend决定；.terraform.lock.hcl锁定provider版本和校验信息，是另一种锁。不能用提交依赖锁来防止两个apply并行。force-unlock仅在证实原持锁进程结束并核对lock ID后考虑，误解锁会产生并发状态写入。课堂使用本地state，不能将本地文件锁当作跨机器协作方案。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：依赖锁是否能阻止两个人同时写state？</p><details><summary>参考解答</summary><p>不能。.terraform.lock.hcl控制provider选择和校验，状态写锁由backend机制提供，二者独立。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p>',29)])])}const f=e(s,[["render",l]]);export{h as __pageData,f as default};
